"""Expose a loaded choice model through explicit DMBench projection recipes."""

from __future__ import annotations

from collections.abc import Callable
from typing import TYPE_CHECKING, Literal, cast

from wyat.core import Candidate, Decision, Model, Request

if TYPE_CHECKING:
    from dmbench.api import Prediction as DMBenchPrediction
    from dmbench.api import Request as DMBenchRequest

type DMBenchRecipe = Literal["dmbench-verbatim-choice-v1", "dmbench-native-choice-v1"]


def as_dmbench(
    model: Model, *, recipe: DMBenchRecipe = "dmbench-verbatim-choice-v1"
) -> Callable[[DMBenchRequest], DMBenchPrediction]:
    """Preserve choices; use public text verbatim unless native roles are selected.

    DMBench owns loading cases, labels, scoring, grouping and provenance. A
    DMBench task identifies its panel; Wyat's task identifies the choice head.
    Choiceless tasks cannot be represented by this adapter. Inference errors
    propagate to the DMBench evaluator, which retains their denominator.
    """
    batch = as_dmbench_batch(model, recipe=recipe)

    def predict(public: DMBenchRequest) -> DMBenchPrediction:
        return batch((public,))[0]

    return predict


def _request(public: DMBenchRequest, recipe: DMBenchRecipe) -> Request:
    query = public.text
    context = ""
    if recipe == "dmbench-native-choice-v1":
        if public.task != "jevbench/choice":
            raise ValueError("Wyat's native recipe requires jevbench/choice")
        from dmbench.adapters.native import native_request
        from dmbench.api import canonical_json

        state, question, _ = native_request(public)
        # native_request validates the declared schema, including this text type.
        query = cast(str, question["instructions"])
        context = state if isinstance(state, str) else canonical_json(state)
    if not public.choices:
        raise ValueError("Wyat's choice adapter requires supplied DMBench choices")
    return Request(
        query=query,
        context=context,
        candidates=tuple(
            Candidate(choice.id, choice.text) for choice in public.choices
        ),
        task="choice",
    )


def as_dmbench_batch(
    model: Model, *, recipe: DMBenchRecipe = "dmbench-verbatim-choice-v1"
) -> Callable[[tuple[DMBenchRequest, ...]], tuple[DMBenchPrediction, ...]]:
    """Expose native batching; validate the entire public chunk before inference.

    Inputs and predictions retain caller order. No concurrency, retry, loading
    or hidden menu reduction is introduced. Scalar and batch calls share the
    same public request and prediction conversions.
    """
    if recipe not in {"dmbench-verbatim-choice-v1", "dmbench-native-choice-v1"}:
        raise ValueError("Unknown DMBench choice adapter recipe")
    from dmbench.api import Prediction

    def prediction(public: DMBenchRequest, decision: Decision) -> DMBenchPrediction:
        return Prediction(
            answer=decision.selected,
            probabilities=dict(
                zip(
                    (choice.id for choice in public.choices),
                    decision.probabilities,
                    strict=True,
                )
            ),
        )

    def predict_many(
        public: tuple[DMBenchRequest, ...],
    ) -> tuple[DMBenchPrediction, ...]:
        if not public:
            return ()
        requests = tuple(_request(request, recipe) for request in public)
        decisions = model.decide_many(requests)
        return tuple(
            prediction(request, decision)
            for request, decision in zip(public, decisions, strict=True)
        )

    return predict_many

"""Validate local Kai configuration, storage and content identity before loading."""

from __future__ import annotations

import hashlib
import math
import struct
from dataclasses import dataclass
from pathlib import Path

from wyat.wire import JsonObject, JsonValue, decode_json, read_object

ARCHITECTURE = "qwen3-text-endpoints-global-query-shared-bilinear-mlp"


PROMPT_VERSION = "decision2-segmented-options-global-query-v1"


def positive_integer(value: object, name: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def normalize_config(raw: JsonObject) -> JsonObject:
    if raw.get("model_type") != "qwen3":
        raise ValueError("Kai backend requires a Qwen3 text backbone")
    if raw.get("hidden_act", "silu") != "silu":
        raise ValueError("Kai requires the SiLU backbone activation")
    config = dict(raw)
    layers = config.get("layer_types")
    if layers is not None and (
        not isinstance(layers, list)
        or any(layer != "full_attention" for layer in layers)
    ):
        raise ValueError("Kai requires full causal attention in every layer")
    if config.get("use_sliding_window", False):
        raise ValueError("Kai does not support sliding-window attention")
    rotary = config.pop("rope_parameters", None)
    if rotary is not None:
        if (
            not isinstance(rotary, dict)
            or rotary.get("rope_type") != "default"
            or set(rotary) - {"rope_type", "rope_theta"}
            or "rope_theta" not in rotary
            or config.get("rope_scaling") is not None
            or ("rope_theta" in config and config["rope_theta"] != rotary["rope_theta"])
        ):
            raise ValueError("Unsupported or contradictory rotary configuration")
        config["rope_theta"] = rotary["rope_theta"]
    elif config.get("rope_scaling") is not None:
        raise ValueError("Kai requires the unscaled default rotary recipe")
    theta = config.get("rope_theta", 10000.0)
    if (
        isinstance(theta, bool)
        or not isinstance(theta, (float, int))
        or not math.isfinite(theta)
        or theta <= 0
    ):
        raise ValueError("Rotary theta must be finite and positive")
    config["rope_theta"] = theta
    return config


@dataclass(frozen=True, slots=True)
class TensorSpec:
    dtype: str
    shape: tuple[int, ...]


def tensor_specs(path: Path) -> dict[str, TensorSpec]:
    """Inspect original storage before a framework can silently cast weights."""
    with path.open("rb") as stream:
        size_bytes = stream.read(8)
        if len(size_bytes) != 8:
            raise ValueError(f"Invalid Safetensors file: {path.name}")
        size = struct.unpack("<Q", size_bytes)[0]
        if size > 8 << 20:
            raise ValueError("Safetensors header exceeds 8 MiB limit")
        header = decode_json(stream.read(size))
    if not isinstance(header, dict):
        raise ValueError("Safetensors header must be an object")
    result: dict[str, TensorSpec] = {}
    for name, value in header.items():
        if name == "__metadata__":
            continue
        if not isinstance(value, dict):
            raise ValueError(f"Invalid tensor specification: {name}")
        dtype, shape = value.get("dtype"), value.get("shape")
        if not isinstance(dtype, str) or not isinstance(shape, list):
            raise ValueError(f"Invalid tensor dtype or shape: {name}")
        dimensions: list[int] = []
        for dimension in shape:
            if type(dimension) is not int or dimension < 0:
                raise ValueError(f"Invalid tensor dimension: {name}")
            dimensions.append(dimension)
        result[name] = TensorSpec(dtype, tuple(dimensions))
    return result


def _declared_hashes(value: JsonValue) -> dict[str, str]:
    if not isinstance(value, dict):
        raise ValueError("Manifest files_sha256 must map names to 64-hex digests")
    result: dict[str, str] = {}
    for name, digest in value.items():
        if (
            not isinstance(digest, str)
            or len(digest) != 64
            or any(char not in "0123456789abcdefABCDEF" for char in digest)
        ):
            raise ValueError("Manifest files_sha256 must map names to 64-hex digests")
        result[name] = digest.lower()
    return result


def _identity(root: Path, declared: dict[str, str] | None) -> str:
    names = [
        "decision_config.json",
        "decision_head.safetensors",
        "backbone/config.json",
        "backbone/model.safetensors",
        "tokenizer.json",
        "tokenizer_config.json",
    ]
    names.extend(
        name
        for name in (
            "config.json",
            "MODEL_MANIFEST.json",
            "special_tokens_map.json",
            "added_tokens.json",
            "vocab.json",
            "merges.txt",
        )
        if (root / name).is_file()
    )
    digest = hashlib.sha256()
    for name in sorted(names):
        file_digest = hashlib.sha256()
        with (root / name).open("rb") as stream:
            for block in iter(lambda: stream.read(8 << 20), b""):
                file_digest.update(block)
        if declared is not None and name in declared:
            if file_digest.hexdigest() != declared[name]:
                raise ValueError(
                    f"Checkpoint file differs from declared digest: {name}"
                )
        digest.update(name.encode("utf-8") + b"\0" + file_digest.digest())
    return "kai:" + digest.hexdigest()


@dataclass(frozen=True, slots=True)
class KaiArtifact:
    root: Path
    config: JsonObject
    head_dim: int
    max_options: int
    model_id: str


def load_artifact(path: str | Path, max_length: int) -> KaiArtifact:
    root = Path(path).resolve(strict=True)
    max_length = positive_integer(max_length, "max_length")
    metadata = read_object(root / "decision_config.json")
    if (
        metadata.get("architecture") != ARCHITECTURE
        or metadata.get("prompt_version") != PROMPT_VERSION
        or metadata.get("head_variant", "shared") != "shared"
        or metadata.get("checkpoint_format") not in (None, "full")
        or metadata.get("readout") not in (None, "candidate")
        or metadata.get("dec_residual") is not None
        or metadata.get("head_compute_dtype", "float32") != "float32"
        or metadata.get("backbone_model_type", "qwen3") != "qwen3"
    ):
        raise ValueError(
            "Unsupported Kai checkpoint architecture, prompt, head or format"
        )
    head_dim = positive_integer(metadata.get("head_dim"), "head_dim")
    max_options = positive_integer(metadata.get("max_options"), "max_options")
    if not 2 <= max_options <= 255:
        raise ValueError("Kai max_options must be within 2..255")
    config = normalize_config(read_object(root / "backbone/config.json"))
    cap = positive_integer(
        config.get("max_position_embeddings"), "max_position_embeddings"
    )
    declared = None
    manifest_path = root / "MODEL_MANIFEST.json"
    if manifest_path.exists():
        manifest = read_object(manifest_path)
        if (
            manifest.get("profile") != "qwen-full"
            or manifest.get("storage") is not None
            or manifest.get("calibration") is not None
        ):
            raise ValueError("Unsupported Kai package profile, storage or calibration")
        cap = min(
            cap, positive_integer(manifest.get("max_input_tokens"), "max_input_tokens")
        )
        if "files_sha256" in manifest:
            declared = _declared_hashes(manifest["files_sha256"])
    if max_length > cap:
        raise ValueError(f"max_length exceeds checkpoint limit {cap}")
    read_object(root / "tokenizer_config.json")
    if (root / "config.json").exists():
        read_object(root / "config.json")
    for name, spec in tensor_specs(root / "backbone/model.safetensors").items():
        if spec.dtype not in {"F32", "BF16"}:
            raise ValueError(f"Unsupported backbone tensor dtype: {name}")
    for name, spec in tensor_specs(root / "decision_head.safetensors").items():
        if spec.dtype != "F32":
            raise ValueError(f"Kai head tensor must use float32: {name}")
    return KaiArtifact(root, config, head_dim, max_options, _identity(root, declared))

"""Immutable decision values and the sole runtime boundary: batches of logits."""

from __future__ import annotations

import math
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from numbers import Real
from typing import Protocol, cast


def _text(value: object, name: str, *, nonempty: bool = False) -> str:
    if not isinstance(value, str) or (nonempty and not value.strip()):
        raise ValueError(f"{name} must be {'nonempty ' if nonempty else ''}text")
    try:
        value.encode("utf-8")
    except UnicodeEncodeError as error:
        raise ValueError(f"{name} must contain valid Unicode") from error
    return value


@dataclass(frozen=True, slots=True)
class Candidate:
    id: str
    text: str

    def __post_init__(self) -> None:
        _text(self.id, "candidate.id", nonempty=True)
        _text(self.text, "candidate.text", nonempty=True)


@dataclass(frozen=True, slots=True)
class Request:
    query: str
    candidates: tuple[Candidate, ...]
    context: str = ""
    task: str = "choice"

    def __post_init__(self) -> None:
        _text(self.query, "query", nonempty=True)
        _text(self.context, "context")
        _text(self.task, "task", nonempty=True)
        if not isinstance(self.candidates, tuple) or not self.candidates:
            raise ValueError("candidates must be a nonempty tuple")
        if not all(isinstance(candidate, Candidate) for candidate in self.candidates):
            raise ValueError("candidates must contain Candidate values")
        ids = [candidate.id for candidate in self.candidates]
        if len(set(ids)) != len(ids):
            raise ValueError("candidate IDs must be unique")


class Scorer(Protocol):
    """Return finite raw logits in request and candidate order.

    Sigmoid scores, embeddings, and calibrated probabilities require their own
    model contracts; they do not satisfy this interface by renaming outputs.
    Implementations own batching, model state, tokenization, and resource limits.
    """

    def score_many(self, requests: Sequence[Request]) -> Sequence[Sequence[float]]: ...


class ModelOutputError(ValueError):
    """A scorer violated its output contract, rather than rejecting an input."""


@dataclass(frozen=True, slots=True)
class Decision:
    model_id: str
    scores: tuple[float, ...]
    probabilities: tuple[float, ...]
    ranking: tuple[str, ...]

    @property
    def selected(self) -> str:
        return self.ranking[0]

    def to_dict(self) -> dict[str, object]:
        return {
            "model_id": self.model_id,
            "selected": self.selected,
            "ranking": list(self.ranking),
            "scores": list(self.scores),
            "probabilities": list(self.probabilities),
        }


def decision_from_logits(
    request: Request, logits: Sequence[float], model_id: str
) -> Decision:
    """Pure interpretation; softmax values are relative, uncalibrated likelihoods."""
    if len(logits) != len(request.candidates):
        raise ModelOutputError("scorer returned a different candidate count")
    if any(isinstance(value, bool) or not isinstance(value, Real) for value in logits):
        raise ModelOutputError("scorer logits must be numbers")
    scores = tuple(float(value) for value in logits)
    if not all(math.isfinite(value) for value in scores):
        raise ModelOutputError("scorer logits must be finite")
    peak = max(scores)
    weights = tuple(math.exp(value - peak) for value in scores)
    total = math.fsum(weights)
    probabilities = tuple(weight / total for weight in weights)
    # Python's stable sort preserves caller order for exact ties.
    order = sorted(range(len(scores)), key=scores.__getitem__, reverse=True)
    return Decision(
        model_id,
        scores,
        probabilities,
        tuple(request.candidates[index].id for index in order),
    )


class Model:
    """A loaded logit scorer. Loading and inference are separate lifetimes."""

    def __init__(self, scorer: Scorer, model_id: str) -> None:
        _text(model_id, "model_id", nonempty=True)
        self._scorer = scorer
        self._model_id = model_id

    @property
    def model_id(self) -> str:
        return self._model_id

    def decide(self, request: Request) -> Decision:
        return self.decide_many((request,))[0]

    def decide_many(self, requests: Sequence[Request]) -> tuple[Decision, ...]:
        batch = tuple(requests)
        if not all(isinstance(request, Request) for request in batch):
            raise ValueError("batch must contain Request values")
        if not batch:
            return ()
        logits = self._scorer.score_many(batch)
        if len(logits) != len(batch):
            raise ModelOutputError("scorer returned a different request count")
        return tuple(
            decision_from_logits(request, scores, self.model_id)
            for request, scores in zip(batch, logits, strict=True)
        )


def request_from_dict(value: object) -> Request:
    if not isinstance(value, Mapping):
        raise ValueError("request must be an object")
    value = cast(Mapping[str, object], value)
    if set(value) - {"query", "candidates", "context", "task"}:
        raise ValueError("unknown request fields")
    if "query" not in value or "candidates" not in value:
        raise ValueError("request requires query and candidates")
    items = value["candidates"]
    if not isinstance(items, list):
        raise ValueError("candidates must be an array")
    candidates: list[Candidate] = []
    for item in items:
        if not isinstance(item, Mapping) or set(item) != {"id", "text"}:
            raise ValueError("candidate requires exactly id and text")
        item = cast(Mapping[str, object], item)
        candidates.append(
            Candidate(
                _text(item["id"], "candidate.id", nonempty=True),
                _text(item["text"], "candidate.text", nonempty=True),
            )
        )
    return Request(
        _text(value["query"], "query", nonempty=True),
        tuple(candidates),
        _text(value.get("context", ""), "context"),
        _text(value.get("task", "choice"), "task", nonempty=True),
    )

"""Pure conversion of explicit JevBench public schemas and native typed answers."""

from __future__ import annotations

import math
from typing import Literal, cast

from ..api import (
    JSONValue,
    Prediction,
    Request,
    Usage,
    canonical_json,
    strict_json_loads,
    validate_request,
)

ScoreMode = Literal["native", "jevbench_argmax"]


def _object(value: JSONValue) -> dict[str, JSONValue]:
    if type(value) is not dict:
        raise ValueError("Native schema requires an object")
    return value


def native_request(request: Request) -> tuple[JSONValue, dict[str, JSONValue], tuple[str, ...]]:
    """Parse only the declared native task; preserve state and question roles."""
    validate_request(request)
    if request.task not in {"jevbench/choice", "jevbench/noul", "jevbench/score"}:
        raise ValueError("Native adapter supports explicit jevbench choice/noul/score tasks only")
    body = _object(strict_json_loads(request.text))
    if set(body) != {"state", "question", "labels"}:
        raise ValueError("Native public body requires exactly state, question and labels")
    question = _object(body["question"])
    if set(question) != {"type", "instructions", "criteria"}:
        raise ValueError("Native question has missing or unknown fields")
    kind = question["type"]
    if request.task != "jevbench/" + str(kind):
        raise ValueError("Native task and question type disagree")
    if type(question["instructions"]) is not str or not question["instructions"].strip():
        raise ValueError("Native instructions must be nonempty text")
    raw_labels = body["labels"]
    if (
        type(raw_labels) is not list
        or not raw_labels
        or any(type(label) is not str or not label for label in raw_labels)
    ):
        raise ValueError("Native labels require nonempty strings")
    labels = tuple(cast(list[str], raw_labels))
    if len(set(labels)) != len(labels):
        raise ValueError("Native labels must be unique")
    criteria = question["criteria"]
    if kind == "score":
        if labels != tuple(str(i) for i in range(len(labels))) or request.choices:
            raise ValueError("Native score requires sequential levels and no choice menu")
        if type(criteria) is not list or len(criteria) != len(labels):
            raise ValueError("Native score rubric does not match its levels")
    else:
        if tuple(choice.id for choice in request.choices) != labels:
            raise ValueError("Native labels and supplied menu order disagree")
        mapping = _object(criteria)
        if kind == "noul":
            if labels != ("no", "yes") or set(mapping) != {"false", "true"}:
                raise ValueError("Native noul requires no/yes and false/true criteria")
            expected_text = {"no": mapping["false"], "yes": mapping["true"]}
        else:
            if set(mapping) != set(labels):
                raise ValueError("Native choice criteria differ from menu")
            expected_text = mapping
        if any(choice.text != expected_text[choice.id] for choice in request.choices):
            raise ValueError("Native criteria and supplied choice text disagree")
        if kind == "choice":
            # Canonical JSON sorts object keys; the explicit menu retains source order.
            question["criteria"] = {label: mapping[label] for label in labels}
    if type(body["state"]) not in (str, dict, list):
        raise ValueError("Native state must be text, an object or a conversation list")
    return body["state"], question, labels


def _number(value: JSONValue, name: str) -> int | float:
    if type(value) not in (int, float) or not math.isfinite(cast(float, value)):
        raise ValueError(f"Native {name} must be a finite number")
    return cast(int | float, value)


def _distribution(value: JSONValue, labels: tuple[str, ...], rounding: float) -> dict[str, float]:
    values = _object(value)
    if set(values) != set(labels):
        raise ValueError("Native probability labels differ from requested labels")
    result = {label: float(_number(values[label], "probability")) for label in labels}
    if any(not 0 <= value <= 1 for value in result.values()):
        raise ValueError("Native probabilities must be in [0, 1]")
    if abs(math.fsum(result.values()) - 1) > len(labels) * rounding + 1e-6:
        raise ValueError("Native probability mass is invalid")
    return result


def decode_native(
    request: Request,
    response: object,
    *,
    score_mode: ScoreMode = "native",
    probability_rounding: float = 0.0,
) -> tuple[Prediction, dict[str, JSONValue]]:
    """Keep native numeric values; an explicit Jev mode chooses ordinal argmax.

    Native rounded distributions never get renormalized. A vector outside the
    core's strict mass tolerance stays only in the caller's raw-response ledger.
    """
    if score_mode not in ("native", "jevbench_argmax"):
        raise ValueError("Unknown native score mode")
    if (
        type(probability_rounding) not in (int, float)
        or not math.isfinite(probability_rounding)
        or probability_rounding < 0
    ):
        raise ValueError("Probability rounding must be finite and nonnegative")
    _, question, labels = native_request(request)
    body = _object(strict_json_loads(canonical_json(response)))
    answers = _object(body.get("answers"))
    if set(answers) != {"decision"}:
        raise ValueError("Native answer IDs differ from requested question")
    answer = _object(answers["decision"])
    if answer.get("type") != question["type"]:
        raise ValueError("Native answer type differs from requested question")
    usage_values = _object(body["usage"]) if body.get("usage") is not None else {}
    usage = (
        Usage(
            cast(int | None, usage_values.get("input_tokens")),
            cast(int | None, usage_values.get("output_tokens")),
            cast(int | None, usage_values.get("forward_passes")),
        )
        if usage_values
        else None
    )
    metadata: dict[str, JSONValue] = {"score_mode": score_mode, "probability_reason": None}
    if answer.get("low_confidence") is True or answer.get("abstention") == "abstained":
        return Prediction(None, "Native backend abstained", usage=usage), metadata
    kind = question["type"]
    probabilities: dict[str, float] | None = None
    if kind == "noul":
        p = _number(answer.get("noul"), "noul")
        if not 0 <= p <= 1:
            raise ValueError("Native noul must be P(true) in [0, 1]")
        result: JSONValue = "yes" if p > 0.5 else "no"
        probabilities = {"no": 1 - float(p), "yes": float(p)}
    elif kind == "choice":
        result = answer.get("choice")
        if type(result) is not str or result not in labels:
            raise ValueError("Native choice is absent from menu")
        if answer.get("probabilities") is not None:
            probabilities = _distribution(answer["probabilities"], labels, probability_rounding)
    else:
        result = _number(answer.get("score"), "score")
        if not 0 <= result <= len(labels) - 1:
            raise ValueError("Native score exceeds its rubric")
        distribution = (
            _distribution(answer["probabilities"], labels, probability_rounding)
            if answer.get("probabilities") is not None
            else None
        )
        if score_mode == "jevbench_argmax":
            if distribution is None:
                raise ValueError("JevBench ordinal argmax requires native probabilities")
            # Match JevBench scoring.py: ties use the lexicographically smallest key.
            result = int(min(distribution, key=lambda label: (-distribution[label], label)))
        metadata["probability_reason"] = "native ordinal distribution retained in raw response"
    if probabilities is not None and not math.isclose(
        math.fsum(probabilities.values()), 1.0, rel_tol=0, abs_tol=1e-6
    ):
        probabilities = None
        metadata["probability_reason"] = (
            "rounded native vector does not meet strict core mass tolerance"
        )
    prediction = Prediction(result, probabilities=probabilities, usage=usage)
    return prediction, metadata

"""Small portable model boundary; supervision never belongs in a Request."""

from __future__ import annotations

import json
import math
from collections.abc import Callable, Sequence
from dataclasses import dataclass
from typing import TypeAlias, cast

JSONValue: TypeAlias = None | bool | int | float | str | list["JSONValue"] | dict[str, "JSONValue"]


def _json(value: object, ancestors: frozenset[int] = frozenset()) -> JSONValue:
    """Validate and detach portable JSON; reject cycles and non-JSON Python types."""
    if value is None or type(value) in (bool, int, str):
        return cast(JSONValue, value)
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("JSON numbers must be finite")
        return value
    if type(value) not in (list, dict):
        raise ValueError("Answer must contain only portable JSON values")
    if id(value) in ancestors:
        raise ValueError("JSON containers cannot contain cycles")
    nested = ancestors | {id(value)}
    if type(value) is list:
        return [_json(item, nested) for item in cast(list[object], value)]
    result: dict[str, JSONValue] = {}
    for key, item in cast(dict[object, object], value).items():
        if type(key) is not str:
            raise ValueError("JSON object keys must be strings")
        result[key] = _json(item, nested)
    return result


def canonical_json(value: object) -> str:
    """Deterministic typed JSON identity, with object order ignored."""
    return json.dumps(_json(value), sort_keys=True, separators=(",", ":"), allow_nan=False)


def strict_json_loads(text: str) -> JSONValue:
    def pairs(items: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, item in items:
            if key in result:
                raise ValueError(f"Duplicate JSON key: {key}")
            result[key] = item
        return result

    def constant(value: str) -> object:
        raise ValueError(f"Nonfinite JSON number: {value}")

    return _json(json.loads(text, object_pairs_hook=pairs, parse_constant=constant))


def _text(value: object, name: str) -> None:
    if type(value) is not str or not value.strip():
        raise ValueError(f"{name} requires a nonempty string")


def _fields(value: object, required: set[str], optional: set[str]) -> dict[str, object]:
    if type(value) is not dict:
        raise ValueError("Schema requires an object")
    record = cast(dict[str, object], value)
    if any(type(key) is not str for key in record):
        raise ValueError("Schema keys must be strings")
    if not required <= record.keys() or record.keys() - required - optional:
        raise ValueError("Schema has missing or unknown fields")
    return record


@dataclass(frozen=True)
class Choice:
    id: str
    text: str

    def __post_init__(self) -> None:
        _text(self.id, "Choice id")
        _text(self.text, "Choice text")


@dataclass(frozen=True)
class Request:
    id: str
    task: str
    text: str
    choices: tuple[Choice, ...] = ()

    def __post_init__(self) -> None:
        validate_request(self)


@dataclass(frozen=True)
class Usage:
    input_tokens: int | None = None
    output_tokens: int | None = None
    forward_passes: int | None = None

    def __post_init__(self) -> None:
        for name in ("input_tokens", "output_tokens", "forward_passes"):
            value = getattr(self, name)
            if value is not None and (
                type(value) is not int or value < (1 if name == "forward_passes" else 0)
            ):
                raise ValueError(f"Invalid usage {name}")


@dataclass(frozen=True)
class Prediction:
    answer: JSONValue
    error: str | None = None
    probabilities: dict[str, float] | None = None
    usage: Usage | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "answer", _json(self.answer))
        if self.probabilities is not None:
            if type(self.probabilities) is not dict:
                raise ValueError("Probabilities require an object")
            object.__setattr__(self, "probabilities", dict(self.probabilities))
        validate_prediction(self)


@dataclass(frozen=True)
class Case:
    request: Request
    expected: tuple[JSONValue, ...]
    group: str
    source: str
    split: str

    def __post_init__(self) -> None:
        if type(self.expected) is not tuple:
            raise ValueError("Expected answers require a tuple")
        object.__setattr__(self, "expected", tuple(_json(item) for item in self.expected))
        validate_case(self)


Model: TypeAlias = Callable[[Request], Prediction | JSONValue]
BatchModel: TypeAlias = Callable[[tuple[Request, ...]], Sequence[Prediction | JSONValue]]


def validate_request(request: Request) -> None:
    if not isinstance(request, Request):
        raise ValueError("Request required")
    for name in ("id", "task", "text"):
        _text(getattr(request, name), f"Request {name}")
    if type(request.choices) is not tuple or any(
        not isinstance(choice, Choice) for choice in request.choices
    ):
        raise ValueError("Choices require a tuple of Choice values")
    ids: set[str] = set()
    for choice in request.choices:
        _text(choice.id, "Choice id")
        _text(choice.text, "Choice text")
        if choice.id in ids:
            raise ValueError("Duplicate choice id")
        ids.add(choice.id)


def validate_prediction(prediction: Prediction, request: Request | None = None) -> None:
    if not isinstance(prediction, Prediction):
        raise ValueError("Prediction required")
    if request is not None:
        validate_request(request)
    _json(prediction.answer)
    if prediction.error is not None:
        _text(prediction.error, "Prediction error")
        if prediction.answer is not None or prediction.probabilities is not None:
            raise ValueError("Errors require null answer and no probabilities")
    if prediction.usage is not None:
        if not isinstance(prediction.usage, Usage):
            raise ValueError("Usage required")
        prediction.usage.__post_init__()
    probabilities = prediction.probabilities
    if probabilities is not None:
        if type(probabilities) is not dict or not probabilities:
            raise ValueError("Probabilities require a nonempty object")
        for key, value in probabilities.items():
            _text(key, "Probability choice id")
            if type(value) not in (int, float) or not math.isfinite(value) or not 0 <= value <= 1:
                raise ValueError("Probabilities must be finite numbers in [0, 1]")
        if not math.isclose(math.fsum(probabilities.values()), 1.0, rel_tol=0, abs_tol=1e-6):
            raise ValueError("Probabilities must sum to one")
        if request is not None:
            if not request.choices or set(probabilities) != {c.id for c in request.choices}:
                raise ValueError("Probabilities must cover exactly the supplied choices")


def validate_case(case: Case) -> None:
    if not isinstance(case, Case):
        raise ValueError("Case required")
    validate_request(case.request)
    for name in ("group", "source", "split"):
        _text(getattr(case, name), f"Case {name}")
    if type(case.expected) is not tuple or not case.expected:
        raise ValueError("Case requires at least one expected answer")
    choices = {choice.id for choice in case.request.choices}
    for answer in case.expected:
        _json(answer)
        if choices and (type(answer) is not str or answer not in choices):
            raise ValueError("Expected choice answer is absent from menu")


def request_to_dict(request: Request) -> dict[str, JSONValue]:
    validate_request(request)
    return {
        "id": request.id,
        "task": request.task,
        "text": request.text,
        "choices": [{"id": c.id, "text": c.text} for c in request.choices],
    }


def request_from_dict(value: object) -> Request:
    record = _fields(value, {"id", "task", "text"}, {"choices"})
    raw = record.get("choices", [])
    if type(raw) is not list:
        raise ValueError("Choices schema requires a list")
    choices = []
    for item in cast(list[object], raw):
        choice = _fields(item, {"id", "text"}, set())
        choices.append(Choice(cast(str, choice["id"]), cast(str, choice["text"])))
    return Request(
        cast(str, record["id"]),
        cast(str, record["task"]),
        cast(str, record["text"]),
        tuple(choices),
    )


def prediction_to_dict(prediction: Prediction) -> dict[str, JSONValue]:
    validate_prediction(prediction)
    usage = prediction.usage
    return {
        "answer": _json(prediction.answer),
        "error": prediction.error,
        "probabilities": _json(prediction.probabilities),
        "usage": None
        if usage is None
        else {
            "input_tokens": usage.input_tokens,
            "output_tokens": usage.output_tokens,
            "forward_passes": usage.forward_passes,
        },
    }


def prediction_from_dict(value: object, request: Request | None = None) -> Prediction:
    record = _fields(value, {"answer"}, {"error", "probabilities", "usage"})
    raw_usage = record.get("usage")
    usage = None
    if raw_usage is not None:
        fields = _fields(raw_usage, set(), {"input_tokens", "output_tokens", "forward_passes"})
        usage = Usage(
            cast(int | None, fields.get("input_tokens")),
            cast(int | None, fields.get("output_tokens")),
            cast(int | None, fields.get("forward_passes")),
        )
    raw_probabilities = record.get("probabilities")
    if raw_probabilities is not None and type(raw_probabilities) is not dict:
        raise ValueError("Probabilities schema requires an object")
    prediction = Prediction(
        _json(record["answer"]),
        cast(str | None, record.get("error")),
        cast(dict[str, float] | None, raw_probabilities),
        usage,
    )
    validate_prediction(prediction, request)
    return prediction


def case_to_dict(case: Case) -> dict[str, JSONValue]:
    validate_case(case)
    return {
        "request": request_to_dict(case.request),
        "expected": [_json(item) for item in case.expected],
        "group": case.group,
        "source": case.source,
        "split": case.split,
    }


def case_from_dict(value: object) -> Case:
    record = _fields(value, {"request", "expected", "group", "source", "split"}, set())
    expected = record["expected"]
    if type(expected) is not list:
        raise ValueError("Expected schema requires a list")
    return Case(
        request_from_dict(record["request"]),
        tuple(_json(item) for item in cast(list[object], expected)),
        cast(str, record["group"]),
        cast(str, record["source"]),
        cast(str, record["split"]),
    )


def normalize_prediction(value: Prediction | JSONValue, request: Request) -> Prediction:
    """Detach an explicit envelope or wrap a native answer without repairing it."""
    prediction = (
        Prediction(value.answer, value.error, value.probabilities, value.usage)
        if isinstance(value, Prediction)
        else Prediction(value)
    )
    validate_prediction(prediction, request)
    return prediction

"""Sequential evaluation with complete preflight and an isolated public boundary."""

from __future__ import annotations

import hashlib
import math
import time
from collections import defaultdict
from collections.abc import Iterable, Sequence
from typing import cast

from .api import (
    BatchModel,
    Case,
    JSONValue,
    Model,
    Prediction,
    Request,
    canonical_json,
    normalize_prediction,
    prediction_from_dict,
    prediction_to_dict,
)

Group = tuple[str, str, str]


def _group(case: Case) -> Group:
    return case.source, case.split, case.group


def _fraction(correct: int, count: int) -> float | None:
    return correct / count if count else None


def _summary(
    indices: list[int],
    correct: list[bool],
    groups: dict[Group, set[int]],
) -> dict[str, object]:
    members = set(indices)
    complete = [positions for positions in groups.values() if positions <= members]
    groups_correct = sum(all(correct[index] for index in positions) for positions in complete)
    total = sum(correct[index] for index in indices)
    return {
        "count": len(indices),
        "correct": total,
        "accuracy": _fraction(total, len(indices)),
        "complete_groups": {
            "count": len(complete),
            "correct": groups_correct,
            "accuracy": _fraction(groups_correct, len(complete)),
        },
    }


def _classification(
    cases: tuple[Case, ...], predictions: list[Prediction]
) -> list[dict[str, object]]:
    """No averaging across unrelated option identities or ambiguous gold sets."""
    panels: dict[tuple[str, str, str], list[int]] = defaultdict(list)
    for index, case in enumerate(cases):
        panels[case.source, case.request.task, case.split].append(index)
    reports: list[dict[str, object]] = []
    for (source, task, split), indices in sorted(panels.items()):
        ids = {choice.id for choice in cases[indices[0]].request.choices}
        texts = {choice.id: choice.text for choice in cases[indices[0]].request.choices}
        if not ids or any(
            {choice.id for choice in cases[index].request.choices} != ids
            or {choice.id: choice.text for choice in cases[index].request.choices} != texts
            or len(cases[index].expected) != 1
            for index in indices
        ):
            continue
        labels = sorted(ids)
        positions = {label: i for i, label in enumerate(labels)}
        matrix = [[0] * (len(labels) + 1) for _ in labels]
        brier: list[float] = []
        log_loss: list[float] = []
        zero_gold_probability = 0
        for index in indices:
            expected = cast(str, cases[index].expected[0])
            prediction = predictions[index]
            selected = prediction.answer
            column = (
                positions[selected]
                if prediction.error is None and type(selected) is str and selected in ids
                else len(labels)
            )
            matrix[positions[expected]][column] += 1
            if prediction.probabilities is not None:
                probabilities = prediction.probabilities
                brier.append(
                    sum((probabilities[label] - int(label == expected)) ** 2 for label in labels)
                )
                if probabilities[expected] == 0:
                    zero_gold_probability += 1
                else:
                    log_loss.append(-math.log(probabilities[expected]))
        support = [sum(row) for row in matrix]
        recall = {label: _fraction(matrix[i][i], support[i]) for i, label in enumerate(labels)}
        f1 = []
        for i, count in enumerate(support):
            if count:
                predicted = sum(row[i] for row in matrix)
                f1.append(2 * matrix[i][i] / (count + predicted))
        valid_recall = [value for value in recall.values() if value is not None]
        reports.append(
            {
                "source": source,
                "task": task,
                "split": split,
                "count": len(indices),
                "labels": labels,
                "recall": recall,
                "balanced_accuracy": sum(valid_recall) / len(valid_recall),
                "macro_f1": sum(f1) / len(f1),
                "macro_classes": [label for label, n in zip(labels, support, strict=True) if n],
                "confusion": {"rows": labels, "columns": [*labels, "<invalid>"], "counts": matrix},
                "calibration": {
                    "probability_count": len(brier),
                    "coverage": _fraction(len(brier), len(indices)),
                    "multiclass_brier": sum(brier) / len(brier) if brier else None,
                    "log_loss": sum(log_loss) / len(log_loss)
                    if log_loss and not zero_gold_probability
                    else None,
                    "log_loss_infinite": bool(zero_gold_probability),
                    "zero_gold_probability_count": zero_gold_probability,
                },
            }
        )
    return reports


def _preflight(cases: Iterable[Case]) -> tuple[tuple[Case, ...], dict[Group, set[int]]]:
    snapshots: list[Case] = []
    for case in cases:
        if not isinstance(case, Case):
            raise ValueError("Case required")
        # Request/Choice fields are immutable. Case construction validates them
        # and detaches mutable expected JSON without a schema roundtrip.
        snapshots.append(Case(case.request, case.expected, case.group, case.source, case.split))
    frozen = tuple(snapshots)
    ids: set[str] = set()
    source_groups: dict[tuple[str, str], str] = {}
    groups: dict[Group, set[int]] = defaultdict(set)
    for index, case in enumerate(frozen):
        if case.request.id in ids:
            raise ValueError("Duplicate request id")
        ids.add(case.request.id)
        key = case.source, case.group
        if source_groups.setdefault(key, case.split) != case.split:
            raise ValueError("Source group crosses splits")
        groups[_group(case)].add(index)
    return frozen, groups


def _report(
    frozen: tuple[Case, ...],
    groups: dict[Group, set[int]],
    predictions: list[Prediction],
    records: list[dict[str, JSONValue]],
) -> dict[str, object]:
    correct = [
        prediction.error is None
        and canonical_json(prediction.answer) in {canonical_json(a) for a in case.expected}
        for case, prediction in zip(frozen, predictions, strict=True)
    ]
    report = _summary(list(range(len(frozen))), correct, groups)
    report["version"] = 1
    for name in ("source", "task", "split"):
        slices: dict[str, list[int]] = defaultdict(list)
        for index, case in enumerate(frozen):
            value = case.request.task if name == "task" else getattr(case, name)
            slices[value].append(index)
        report["by_" + name] = {
            key: _summary(indices, correct, groups) for key, indices in sorted(slices.items())
        }
    report["classification"] = _classification(frozen, predictions)
    report["predictions"] = records
    return report


def _public_request(request: Request) -> Request:
    return Request(
        hashlib.sha256(request.id.encode("utf-8", errors="surrogatepass")).hexdigest(),
        request.task,
        request.text,
        request.choices,
    )


def evaluate(
    cases: Iterable[Case], model: Model, *, batch: BatchModel | None = None, batch_size: int = 1
) -> dict[str, object]:
    """Validate the complete cohort before the first model call; never retry."""
    started = time.perf_counter()
    if not callable(model):
        raise ValueError("Model must be callable")
    if type(batch_size) is not int or batch_size < 1:
        raise ValueError("Batch size must be a positive integer")
    if batch is not None and not callable(batch):
        raise ValueError("Batch model must be callable")
    if batch is None and batch_size != 1:
        raise ValueError("Batch size requires an explicit batch callable")
    # Snapshot all gold and inputs before user code executes or mutates caller data.
    frozen, groups = _preflight(cases)

    predictions: list[Prediction] = []
    records: list[dict[str, JSONValue]] = []
    inference_seconds = 0.0
    batch_count = 0
    if batch is None:
        for case in frozen:
            request = case.request
            public = _public_request(request)
            call_started = time.perf_counter()
            try:
                prediction = normalize_prediction(model(public), public)
            except Exception as error:
                prediction = Prediction(None, f"{type(error).__name__}: {error}")
            elapsed = time.perf_counter() - call_started
            inference_seconds += elapsed
            predictions.append(prediction)
            records.append(
                {"id": request.id, **prediction_to_dict(prediction), "elapsed_seconds": elapsed}
            )
    else:
        for start in range(0, len(frozen), batch_size):
            cohort = frozen[start : start + batch_size]
            public_batch = tuple(_public_request(case.request) for case in cohort)
            call_started = time.perf_counter()
            try:
                raw = batch(public_batch)
                if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes, bytearray)):
                    raise ValueError("Batch must return an ordered sequence of predictions")
                if len(raw) != len(cohort):
                    raise ValueError("Batch prediction count must match request count")
                results: list[Prediction] = []
                for value, request in zip(raw, public_batch, strict=True):
                    try:
                        results.append(normalize_prediction(value, request))
                    except Exception as error:
                        results.append(Prediction(None, f"{type(error).__name__}: {error}"))
            except Exception as error:
                results = [Prediction(None, f"{type(error).__name__}: {error}") for _ in cohort]
            elapsed = time.perf_counter() - call_started
            inference_seconds += elapsed
            for case, prediction in zip(cohort, results, strict=True):
                predictions.append(prediction)
                records.append(
                    {
                        "id": case.request.id,
                        **prediction_to_dict(prediction),
                        "elapsed_seconds": None,
                        "batch_index": batch_count,
                        "batch_elapsed_seconds": elapsed,
                    }
                )
            batch_count += 1
    report = _report(frozen, groups, predictions, records)
    report["timing"] = {
        "elapsed_seconds": time.perf_counter() - started,
        "inference_seconds": inference_seconds,
        "mode": "sequential" if batch is None else "explicit_batch",
        "batch_size": batch_size,
        "batch_count": batch_count,
        "measurement": "model call and output normalization; batch time is not per-item latency",
    }
    return report


def score_predictions(cases: Iterable[Case], records: Iterable[object]) -> dict[str, object]:
    """Re-score strict saved outputs; missing records fail and extra IDs reject."""
    frozen, groups = _preflight(cases)
    by_id = {case.request.id: case for case in frozen}
    saved: dict[str, tuple[Prediction, dict[str, JSONValue]]] = {}
    for value in records:
        if type(value) is not dict:
            raise ValueError("Prediction record requires an object")
        record = cast(dict[str, object], value)
        if not {"id", "answer"} <= record.keys() or record.keys() - {
            "id",
            "answer",
            "error",
            "probabilities",
            "usage",
            "elapsed_seconds",
            "batch_index",
            "batch_elapsed_seconds",
        }:
            raise ValueError("Prediction record has missing or unknown fields")
        identity = record["id"]
        if type(identity) is not str or identity not in by_id:
            raise ValueError("Unknown prediction id")
        if identity in saved:
            raise ValueError("Duplicate prediction id")
        prediction = prediction_from_dict(
            {
                key: item
                for key, item in record.items()
                if key not in ("id", "elapsed_seconds", "batch_index", "batch_elapsed_seconds")
            },
            by_id[identity].request,
        )
        output: dict[str, JSONValue] = {"id": identity, **prediction_to_dict(prediction)}
        if "elapsed_seconds" in record:
            elapsed = record["elapsed_seconds"]
            if elapsed is None:
                if not {"batch_index", "batch_elapsed_seconds"} <= record.keys():
                    raise ValueError("Null per-item latency requires batch timing")
            elif (
                type(elapsed) not in (float, int)
                or not math.isfinite(cast(float, elapsed))
                or cast(float, elapsed) < 0
            ):
                raise ValueError("Elapsed seconds must be finite and nonnegative")
            output["elapsed_seconds"] = cast(float | None, elapsed)
        if {"batch_index", "batch_elapsed_seconds"} & record.keys():
            if not {"batch_index", "batch_elapsed_seconds", "elapsed_seconds"} <= record.keys():
                raise ValueError("Batch timing fields must be supplied together")
            index, elapsed = record["batch_index"], record["batch_elapsed_seconds"]
            if type(index) is not int or index < 0 or record["elapsed_seconds"] is not None:
                raise ValueError("Invalid batch index or per-item latency")
            if (
                type(elapsed) not in (float, int)
                or not math.isfinite(cast(float, elapsed))
                or cast(float, elapsed) < 0
            ):
                raise ValueError("Batch elapsed seconds must be finite and nonnegative")
            output["batch_index"] = index
            output["batch_elapsed_seconds"] = cast(float, elapsed)
        saved[identity] = prediction, output
    predictions: list[Prediction] = []
    outputs: list[dict[str, JSONValue]] = []
    for case in frozen:
        identity = case.request.id
        prediction, output = saved.get(
            identity,
            (
                Prediction(None, "Missing prediction"),
                {
                    "id": identity,
                    "answer": None,
                    "error": "Missing prediction",
                    "probabilities": None,
                    "usage": None,
                },
            ),
        )
        predictions.append(prediction)
        outputs.append(output)
    return _report(frozen, groups, predictions, outputs)

"""The maintained tokenizer policy and exact segmented Kai request encoding."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import NamedTuple, Protocol, cast

from wyat.core import Request
from wyat.wire import read_object

from .artifact import KaiArtifact, positive_integer

SUFFIX = (
    "\n\nSelect the single option best supported by the context and instructions."
    "\nDecision:"
)


class EncodedRequest(NamedTuple):
    ids: tuple[int, ...]
    candidate_positions: tuple[int, ...]
    query_position: int


class TokenizerProtocol(Protocol):
    @property
    def pad_token_id(self) -> int | None: ...

    @property
    def eos_token_id(self) -> int | None: ...

    def encode(self, text: str, *, add_special_tokens: bool = False) -> list[int]: ...


def load_tokenizer(root: Path) -> TokenizerProtocol:
    from transformers import AutoTokenizer

    config = read_object(root / "tokenizer_config.json")
    if config.get("fast_tokenizer_files"):
        raise ValueError(
            "Alternate tokenizer files require an explicit export contract"
        )
    # HF owns Qwen normalization, configured special tokens and legacy overrides.
    # Direct tokenizer.json loading silently skips those parts of the recipe.
    try:
        return cast(
            TokenizerProtocol,
            AutoTokenizer.from_pretrained(
                root,
                local_files_only=True,
                trust_remote_code=False,
            ),
        )
    except Exception as exc:
        raise ValueError(f"Cannot load local tokenizer: {exc}") from exc


class KaiEncoder:
    """Exact segmented tokens; cached values never contain contextual vectors."""

    def __init__(
        self,
        tokenizer: TokenizerProtocol,
        *,
        max_length: int,
        max_options: int,
        token_cache_size: int = 0,
    ) -> None:
        self.max_length = positive_integer(max_length, "max_length")
        if type(token_cache_size) is not int or token_cache_size < 0:
            raise ValueError("token_cache_size must be a nonnegative integer")
        self.tokenizer = tokenizer
        self.max_options = max_options
        self._option_tokens = lru_cache(maxsize=token_cache_size)(self._tokens)
        self._suffix = self._tokens(SUFFIX)
        pad_id = tokenizer.pad_token_id
        if pad_id is None:
            pad_id = tokenizer.eos_token_id
        if pad_id is None:
            raise ValueError("Tokenizer requires a pad or EOS token")
        self.pad_id = pad_id

    @classmethod
    def from_artifact(
        cls, artifact: KaiArtifact, *, max_length: int, token_cache_size: int = 0
    ) -> KaiEncoder:
        return cls(
            load_tokenizer(artifact.root),
            max_length=max_length,
            max_options=artifact.max_options,
            token_cache_size=token_cache_size,
        )

    def _tokens(self, text: str) -> tuple[int, ...]:
        if len(text.encode("utf-8")) > self.max_length * 32:
            raise ValueError("Input segment exceeds tokenization byte limit")
        ids = tuple(self.tokenizer.encode(text, add_special_tokens=False))
        if not ids or len(ids) > self.max_length:
            raise ValueError(
                "Input segment is empty or exceeds max_length; no truncation"
            )
        return ids

    def encode_request(self, request: Request) -> EncodedRequest:
        if request.task != "choice":
            raise ValueError("Kai currently supports choice requests only")
        if not 2 <= len(request.candidates) <= self.max_options:
            raise ValueError(f"Kai requires 2..{self.max_options} candidates")
        prefix = (
            f"Context:\n{request.context}\n\n"
            f"Task type: choice\nQuestion:\n{request.query}\nOptions:"
        )
        ids = list(self._tokens(prefix))
        positions: list[int] = []
        for candidate in request.candidates:
            payload = json.dumps(
                {"key": candidate.id, "description": candidate.text},
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            ids.extend(self._option_tokens("\n<option>\n" + payload + "\n</option>"))
            positions.append(len(ids) - 1)
        ids.extend(self._suffix)
        if len(ids) > self.max_length:
            raise ValueError(
                f"{len(ids)} tokens exceeds max_length={self.max_length}; no truncation"
            )
        return EncodedRequest(tuple(ids), tuple(positions), len(ids) - 1)

"""Strict JSON decoding shared by the CLI and HTTP boundary."""

import json
import math
from pathlib import Path
from typing import cast

type JsonValue = (
    None | bool | int | float | str | list[JsonValue] | dict[str, JsonValue]
)
type JsonObject = dict[str, JsonValue]


def _object(pairs: list[tuple[str, JsonValue]]) -> JsonObject:
    result: JsonObject = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON field: {key}")
        result[key] = value
    return result


def _constant(value: str) -> None:
    raise ValueError(f"nonfinite JSON number: {value}")


def _float(value: str) -> float:
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError("JSON number exceeds finite float range")
    return parsed


def decode_json(data: str | bytes) -> JsonValue:
    # json.loads is dynamically typed; the decoder only creates JSON values.
    return cast(
        JsonValue,
        json.loads(
            data,
            object_pairs_hook=_object,
            parse_constant=_constant,
            parse_float=_float,
        ),
    )


def read_object(path: Path) -> JsonObject:
    value = decode_json(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"Expected a JSON object: {path.name}")
    return value
